using Crownfall.Battle.Combat; using UnityEngine; namespace Crownfall.Skills { [CreateAssetMenu(fileName="DamageEffect",menuName="Crownfall/Skills/Effects/Damage")] public sealed class DamageEffectDefinition:SkillEffectDefinition { public float flatDamage; public float attackScaling=1; public DamageType damageType=DamageType.Physical; public bool canCrit; public override void Execute(SkillContext c,Crownfall.Units.Unit t){if(t!=null&&t.Team!=c.Caster.Team)c.Damage.Apply(c.Caster,t,flatDamage+c.Caster.Definition.attack*attackScaling,damageType,canCrit);} } }
